// FetchConnector retrieves a single Connectors object by name.
//
// This is a convenience method that uses server-side name filtering to retrieve
// a specific object by its name within a container (folder, snippet, or device).
//
// Parameters:
//   - ctx: Context for the request
//   - name: The name of the object to fetch
//   - folder: The folder in which the resource is defined (optional, use nil if not needed)
//   - snippet: The snippet in which the resource is defined (optional, use nil if not needed)
//   - device: The device in which the resource is defined (optional, use nil if not needed)
//
// Returns:
//   - *Connectors: The matching object if found, nil otherwise
//   - error: Any error that occurred during the fetch operation
//
// Example:
//
//	obj, err := api.FetchConnector(ctx, "my-object", &folder, nil, nil)
//	if err != nil {
//	    return err
//	}
//	if obj != nil {
//	    fmt.Printf("Found object\n")
//	}
func (a *ConnectorAPIService) FetchConnector(ctx context.Context, name string, folder *string, snippet *string, device *string) (*Connectors, error) {
	var offset int32 = 0
	var limit int32 = 5000

	for {
		req := a.ListConnectors(ctx).
			Offset(offset).
			Limit(limit)

		response, _, err := req.Execute()
		if err != nil {
			return nil, err
		}

		// Filter by exact name match
		if response.Data != nil {
			for i := range response.Data {
				if response.Data[i].Name == name {
					return &response.Data[i], nil
				}
			}
		}

		// Check if we've reached the end
		if response.Data == nil || len(response.Data) < int(limit) {
			break
		}

		offset += limit
	}

	return nil, nil
}
